const constructPrefix = (root: string, randomize: boolean = true, path: boolean = true) => {
    const fullPath = path
        ? new Date()
              .toISOString()
              .split(/-|T|:|\./)
              .join('/')
        : new Date()
              .toISOString()
              .split(/-|T|:|\./)
              .join('');
    return `${root}/${fullPath}${randomize ? Math.round(Math.random() * 1000).toString() : ''}.txt`;
};

